//! The atlas layer against the library's patches, at a radius small
//! enough to run in seconds: every ball is regenerated by the library's
//! own driver, and a patch shows nothing the atlas lacks.

use certify::atlas::{ExploreOpts, explore};
use certify::ball::Atlas;
use certify::ctx::Ctx;
use certify::patchctx::PatchCtx;
use certify::validate::{check_patch, check_witnesses};
use tiling_core::{Tiling, TilingFamily};

fn atlas_for(family: TilingFamily, r: u32) -> (Tiling, Atlas) {
    let tiling = Tiling::new(family);
    let mut atlas = Atlas {
        family: String::new(),
        radius: r,
        region_factor: 1.0,
        balls: Vec::new(),
    };
    {
        let ctx = Ctx::new(&tiling);
        let opts = ExploreOpts {
            region_factor: 1.0,
            verify: true,
            full_keys: true,
            log_every: 0,
            max_nodes: 200_000,
            dump: false,
        };
        for &ty in &ctx.base_types {
            let (balls, _, _) = explore(&ctx, ty, r, &opts).expect("exploration terminates");
            atlas.balls.extend(balls);
        }
    }
    (tiling, atlas)
}

fn check(family: TilingFamily, r: u32, expected: usize) {
    let (tiling, atlas) = atlas_for(family, r);
    assert_eq!(atlas.balls.len(), expected, "{family:?} R={r} ball count");
    let ctx = Ctx::new(&tiling);
    let w = check_witnesses(&atlas, &ctx);
    assert!(
        w.failures.is_empty(),
        "{family:?}: witness failures {:?}",
        &w.failures[..w.failures.len().min(3)]
    );
    let pctx = PatchCtx::new(&ctx, &tiling.default_root(), 24);
    let p = check_patch(&atlas, &pctx, 1);
    assert!(p.checked > 100);
    assert!(p.missing.is_empty(), "{family:?}: patch balls missing from atlas");
    assert!(p.vadj_mismatch.is_empty(), "{family:?}: vertex adjacency mismatch");
}

#[test]
fn hat_2_balls_match_library_patches() {
    // 118 legal 2-balls (11 antihat-centred, 107 hat-centred): FINDINGS §10.11.
    check(TilingFamily::Hat, 2, 118);
}

#[test]
fn spectre_2_balls_match_library_patches() {
    let (tiling, atlas) = atlas_for(TilingFamily::Spectre, 2);
    assert!(atlas.balls.len() > 20);
    let ctx = Ctx::new(&tiling);
    let w = check_witnesses(&atlas, &ctx);
    assert!(w.failures.is_empty());
    let pctx = PatchCtx::new(&ctx, &tiling.default_root(), 24);
    let p = check_patch(&atlas, &pctx, 1);
    assert!(p.missing.is_empty() && p.vadj_mismatch.is_empty());
}
